package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"
)

// Login is one signed-in browser. The token is the whole credential, so it is
// generated by the caller from crypto/rand and never derived from anything.
type Login struct {
	Token     string
	UserID    string
	Label     string
	CreatedAt time.Time
	SeenAt    time.Time
	ExpiresAt time.Time
}

func (l Login) Live(at time.Time) bool {
	return at.Before(l.ExpiresAt)
}

const loginCols = "token, user_id, label, created_at, seen_at, expires_at"

func (s *Store) StartLogin(ctx context.Context, l Login) (Login, error) {
	now := s.now()
	l.CreatedAt = now
	l.SeenAt = now

	_, err := s.db.ExecContext(ctx,
		"INSERT INTO logins ("+loginCols+") VALUES (?, ?, ?, ?, ?, ?)",
		l.Token, l.UserID, l.Label,
		formatTime(l.CreatedAt), formatTime(l.SeenAt), formatTime(l.ExpiresAt),
	)
	if err != nil {
		return Login{}, fmt.Errorf("starting a login: %w", err)
	}

	return l, nil
}

// WhoIs resolves a token to its user in one query. An expired token is treated as
// no token at all rather than as a different kind of failure.
func (s *Store) WhoIs(ctx context.Context, token string) (User, Login, error) {
	row := s.db.QueryRowContext(ctx, `
		SELECT `+prefixed("l", loginCols)+`, `+prefixed("u", userColumns)+`
		FROM logins l JOIN users u ON u.id = l.user_id
		WHERE l.token = ?`, token)

	var (
		l         Login
		u         User
		lc, ls, x string
		uc, uu    string
	)

	err := row.Scan(&l.Token, &l.UserID, &l.Label, &lc, &ls, &x,
		&u.ID, &u.Username, &u.DisplayName, &u.Role, &uc, &uu)
	if errors.Is(err, sql.ErrNoRows) {
		return User{}, Login{}, ErrNotFound
	}
	if err != nil {
		return User{}, Login{}, fmt.Errorf("resolving a token: %w", err)
	}

	for dst, raw := range map[*time.Time]string{
		&l.CreatedAt: lc, &l.SeenAt: ls, &l.ExpiresAt: x,
		&u.CreatedAt: uc, &u.UpdatedAt: uu,
	} {
		t, err := parseTime(raw)
		if err != nil {
			return User{}, Login{}, err
		}
		*dst = t
	}

	if !l.Live(s.now()) {
		return User{}, Login{}, ErrNotFound
	}

	return u, l, nil
}

// TouchLogin only writes when the stored time is stale, so an idle tab polling
// every few seconds does not turn every read into a write.
func (s *Store) TouchLogin(ctx context.Context, token string, stale time.Duration) error {
	cut := formatTime(s.now().Add(-stale))

	_, err := s.db.ExecContext(ctx,
		"UPDATE logins SET seen_at = ? WHERE token = ? AND seen_at < ?",
		formatTime(s.now()), token, cut)
	if err != nil {
		return fmt.Errorf("touching a login: %w", err)
	}

	return nil
}

func (s *Store) EndLogin(ctx context.Context, token string) error {
	if _, err := s.db.ExecContext(ctx, "DELETE FROM logins WHERE token = ?", token); err != nil {
		return fmt.Errorf("ending a login: %w", err)
	}
	return nil
}

// EndAllLogins is what a password change hangs off: every other browser is signed
// out, which is the point of changing it.
func (s *Store) EndAllLogins(ctx context.Context, userID string) (int, error) {
	res, err := s.db.ExecContext(ctx, "DELETE FROM logins WHERE user_id = ?", userID)
	if err != nil {
		return 0, fmt.Errorf("ending logins for %s: %w", userID, err)
	}

	n, err := res.RowsAffected()
	if err != nil {
		return 0, fmt.Errorf("ending logins for %s: %w", userID, err)
	}

	return int(n), nil
}

func (s *Store) SweepLogins(ctx context.Context) (int, error) {
	res, err := s.db.ExecContext(ctx, "DELETE FROM logins WHERE expires_at <= ?", formatTime(s.now()))
	if err != nil {
		return 0, fmt.Errorf("sweeping logins: %w", err)
	}

	n, err := res.RowsAffected()
	if err != nil {
		return 0, fmt.Errorf("sweeping logins: %w", err)
	}

	return int(n), nil
}

func (s *Store) LoginsFor(ctx context.Context, userID string) ([]Login, error) {
	rows, err := s.db.QueryContext(ctx,
		"SELECT "+loginCols+" FROM logins WHERE user_id = ? ORDER BY created_at DESC", userID)
	if err != nil {
		return nil, fmt.Errorf("listing logins: %w", err)
	}
	defer rows.Close()

	out := []Login{}

	for rows.Next() {
		var (
			l         Login
			c, se, ex string
		)

		if err := rows.Scan(&l.Token, &l.UserID, &l.Label, &c, &se, &ex); err != nil {
			return nil, fmt.Errorf("listing logins: %w", err)
		}

		if l.CreatedAt, err = parseTime(c); err != nil {
			return nil, err
		}
		if l.SeenAt, err = parseTime(se); err != nil {
			return nil, err
		}
		if l.ExpiresAt, err = parseTime(ex); err != nil {
			return nil, err
		}

		out = append(out, l)
	}

	return out, rows.Err()
}

// prefixed turns "a, b" into "x.a, x.b" so a join can reuse the column lists the
// rest of the package already defines.
func prefixed(alias, cols string) string {
	parts := splitCols(cols)
	for i, c := range parts {
		parts[i] = alias + "." + c
	}
	return joinCols(parts)
}
